+func TestScopedWorkspaceIDs_ValidUUIDs(t *testing.T) {
+	wsID1 := "11111111-1111-1111-1111-111111111111"
+	wsID2 := "22222222-2222-2222-2222-222222222222"
+
+	ctx := authmw.SetAuthCtx(context.Background(), &authmw.AuthCtx{
+		UserID:                 "u1",
+		OrganizationID:         "o1",
+		AccessibleWorkspaceIDs: []string{wsID1, wsID2},
+	})
+
+	ids, ok := database.ScopedWorkspaceIDs(ctx)
+	if !ok {
+		t.Error("expected ok=true when auth context is present")
+	}
+	if len(ids) != 2 {
+		t.Fatalf("expected 2 UUIDs, got %d", len(ids))
+	}
