content.content:
1	package database
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"strings"
8	
9		"github.com/jackc/pgx/v5"
10		"github.com/jackc/pgx/v5/pgtype"
11	
12		"github.com/tiendv89/workflow-backend/internal/authmw"
13	)
14	
15	// ErrNotFound is returned when a queried row does not exist.
16	var ErrNotFound = errors.New("not found")
17	
18	// ScopedWorkspaceIDs extracts the caller's accessible workspace UUIDs from the auth
19	// context and returns them for use in query WHERE clauses.
20	// Returns (nil, false) when no auth context is present (unauthenticated path).
21	// Returns ([]pgtype.UUID{}, true) when the user has zero accessible workspaces.
22	func ScopedWorkspaceIDs(ctx context.Context) ([]pgtype.UUID, bool) {
23		ac, ok := authmw.FromContext(ctx)
24		if !ok {
25			return nil, false
26		}
27		uids := make([]pgtype.UUID, 0, len(ac.AccessibleWorkspaceIDs))
28		for _, idStr := range ac.AccessibleWorkspaceIDs {
29			var uid pgtype.UUID
30			if uid.Scan(idStr) == nil {
31				uids = append(uids, uid)
32			}
33		}
34		return uids, true
35	}
36	
37	// Reader executes read-only SQL queries against the shared PostgreSQL schema.
38	// All UUID parameters are accepted as hex strings and parsed internally.
39	type Reader struct {
40		db *Pool
41	}
42	
43	// FeatureSearchFilters contains optional filters and result controls for feature search.
44	type FeatureSearchFilters struct {
45		Title  string
46		Status string
47		Sort   string
48		Page   int
49		Limit  int
50	}
51	
52	// TaskSearchFilters contains optional filters and result controls for task search.
53	type TaskSearchFilters struct {
54		TaskID string
55		Title  string
56		Status string
57		Repo   string
58		Sort   string
59		Page   int
60		Limit  int
61	}
62	
63	// NewReader creates a new Reader.
64	func NewReader(db *Pool) *Reader {
65		return &Reader{db: db}
66	}
67	
68	// ListWorkspaces returns workspaces visible to the caller ordered by updated_at desc.
69	// When an auth context is present the result is filtered to the caller's accessible
70	// workspace IDs; a user with zero accessible workspaces gets an empty list.
71	func (r *Reader) ListWorkspaces(ctx context.Context) ([]Workspace, error) {
72		accessible, hasAuth := ScopedWorkspaceIDs(ctx)
73		if hasAuth && len(accessible) == 0 {
74			return []Workspace{}, nil
75		}
76	
77		var (
78			q    string
79			args []interface{}
80		)
81		if hasAuth {
82			q = `
83			SELECT id, organization_id, slug, name, management_repo_id, branch_pattern, created_at, updated_at
84			FROM workspaces
85			WHERE id = ANY($1)
86			ORDER BY updated_at DESC`
87			args = []interface{}{accessible}
88		} else {
89			q = `
90			SELECT id, organization_id, slug, name, management_repo_id, branch_pattern, created_at, updated_at
91			FROM workspaces
92			ORDER BY updated_at DESC`
93		}
94	
95		rows, err := r.db.Query(ctx, q, args...)
96		if err != nil {
97			return nil, err
98		}
99		defer rows.Close()
100		var out []Workspace
101		for rows.Next() {
102			var w Workspace
103			if err := rows.Scan(&w.ID, &w.OrganizationID, &w.Slug, &w.Name, &w.ManagementRepoID, &w.BranchPattern, &w.CreatedAt, &w.UpdatedAt); err != nil {
104				return nil, err
105			}
106			out = append(out, w)
107		}
108		return out, rows.Err()
109	}
110	
111	// GetWorkspace returns a single workspace by UUID string.
112	// Returns ErrNotFound if no row exists or the workspace is not in the caller's
113	// accessible set (cross-tenant isolation: 404, not 403).
114	func (r *Reader) GetWorkspace(ctx context.Context, workspaceID string) (Workspace, error) {
115		uid, err := parseUUID(workspaceID)
116		if err != nil {
117			return Workspace{}, err
118		}
119	
120		accessible, hasAuth := ScopedWorkspaceIDs(ctx)
121		if hasAuth && len(accessible) == 0 {
122			return Workspace{}, ErrNotFound
123		}
124	
