297	// SearchWorkspaceFeatures returns workspace features filtered by search/title/status with safe sorting and limiting.
298	func (r *Reader) SearchWorkspaceFeatures(ctx context.Context, workspaceID string, filters FeatureSearchFilters) ([]WorkspaceFeature, error) {
299		uid, err := parseUUID(workspaceID)
300		if err != nil {
301			return nil, err
302		}
303	
304		where, args, argPos := buildFeatureWhere(uid, filters)
305	
306		orderBy := "updated_at DESC, feature_name ASC"
307		switch filters.Sort {
308		case "title_asc":
309			orderBy = "title ASC, feature_name ASC"
310		case "title_desc":
311			orderBy = "title DESC, feature_name ASC"
312		case "status_asc":
313			orderBy = "feature_status ASC NULLS LAST, feature_name ASC"
314		case "status_desc":
315			orderBy = "feature_status DESC NULLS LAST, feature_name ASC"
316		case "updated_at_asc", "time_asc", "createdAt":
317			orderBy = "updated_at ASC, feature_name ASC"
318		case "updated_at_desc", "time_desc", "-createdAt", "":
319			orderBy = "updated_at DESC, feature_name ASC"
320		}
321	
322		limitClause := ""
323		if filters.Limit > 0 {
324			limitClause = fmt.Sprintf(" LIMIT $%d", argPos)
325			args = append(args, filters.Limit)
326			argPos++
327		}
328		offsetClause := ""
329		if filters.Page > 1 && filters.Limit > 0 {
330			offsetClause = fmt.Sprintf(" OFFSET $%d", argPos)
331			args = append(args, (filters.Page-1)*filters.Limit)
332		}
333	
334		q := fmt.Sprintf(`
335			SELECT id, workspace_id, feature_id, feature_name, title, feature_status, current_stage, next_action,
336			       stages, source_path, source_hash, created_at, updated_at
337			FROM workspace_features
338			WHERE %s
339			ORDER BY %s%s%s`, strings.Join(where, " AND "), orderBy, limitClause, offsetClause)
340		rows, err := r.db.Query(ctx, q, args...)
341		if err != nil {
342			return nil, err
343		}
344		defer rows.Close()
345		var out []WorkspaceFeature
346		for rows.Next() {
347			var f WorkspaceFeature
348			if err := scanFeature(rows, &f); err != nil {
349				return nil, err
350			}
351			out = append(out, f)
352		}
353		return out, rows.Err()
354	}
