356	// ListFeatureTaskCounts returns aggregated task counts for the requested features.
357	func (r *Reader) ListFeatureTaskCounts(ctx context.Context, workspaceID string, featureIDs []string) ([]WorkspaceFeatureTaskCounts, error) {
358		uid, err := parseUUID(workspaceID)
359		if err != nil {
360			return nil, err
361		}
362		if len(featureIDs) == 0 {
363			return []WorkspaceFeatureTaskCounts{}, nil
364		}
365	
366		args := make([]interface{}, 1, len(featureIDs)+1)
367		args[0] = uid
368		placeholders := make([]string, 0, len(featureIDs))
369		for _, featureID := range featureIDs {
370			fid, parseErr := parseUUID(featureID)
371			if parseErr != nil {
372				return nil, parseErr
373			}
374			args = append(args, fid)
375			placeholders = append(placeholders, fmt.Sprintf("$%d", len(args)))
376		}
377	
378		const qTemplate = `
379			SELECT feature_id,
380			       count(*) AS total,
381			       count(*) FILTER (WHERE status = 'done') AS done,
382			       count(*) FILTER (WHERE status = 'in_progress') AS in_progress,
383			       count(*) FILTER (WHERE status = 'blocked') AS blocked,
384			       count(*) FILTER (WHERE status = 'ready') AS ready,
385			       count(*) FILTER (WHERE status = 'todo') AS todo
386			FROM workspace_tasks
387			WHERE workspace_id = $1 AND feature_id IN (%s)
388			GROUP BY feature_id`
389		q := fmt.Sprintf(qTemplate, strings.Join(placeholders, ", "))
390		rows, err := r.db.Query(ctx, q, args...)
391		if err != nil {
392			return nil, err
393		}
394		defer rows.Close()
395	
396		var out []WorkspaceFeatureTaskCounts
397		for rows.Next() {
398			var row WorkspaceFeatureTaskCounts
399			if err := rows.Scan(&row.FeatureID, &row.Total, &row.Done, &row.InProgress, &row.Blocked, &row.Ready, &row.Todo); err != nil {
400				return nil, err
401			}
402			out = append(out, row)
403		}
404		return out, rows.Err()
405	}
