657	// UUIDString converts a pgtype.UUID to its hex string representation.
658	func UUIDString(u pgtype.UUID) string {
659		if !u.Valid {
660			return ""
661		}
662		b := u.Bytes
663		return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x",
664			b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
665	}
