677	// buildFeatureWhere constructs the WHERE clause conditions for feature search/count queries.
678	func buildFeatureWhere(workspaceUID pgtype.UUID, filters FeatureSearchFilters) ([]string, []interface{}, int) {
679		where := []string{"workspace_id = $1"}
680		args := []interface{}{workspaceUID}
681		argPos := 2
682		if filters.Title != "" {
683			where = append(where, fmt.Sprintf("title ILIKE $%d", argPos))
684			args = append(args, "%"+filters.Title+"%")
685			argPos++
686		}
687		if filters.Status != "" {
688			statuses := splitCSV(filters.Status)
689			if len(statuses) == 1 {
690				where = append(where, fmt.Sprintf("feature_status = $%d", argPos))
691				args = append(args, statuses[0])
692				argPos++
693			} else if len(statuses) > 1 {
694				where = append(where, fmt.Sprintf("feature_status = ANY($%d)", argPos))
695				args = append(args, statuses)
696				argPos++
697			}
698		}
699		return where, args, argPos
700	}
