702	// buildTaskWhere constructs the WHERE clause conditions for task search/count queries.
703	func buildTaskWhere(baseWhere []string, baseArgs []interface{}, argPos int, filters TaskSearchFilters) ([]string, []interface{}, int) {
704		where := make([]string, len(baseWhere), len(baseWhere)+4)
705		copy(where, baseWhere)
706		args := make([]interface{}, len(baseArgs), len(baseArgs)+4)
707		copy(args, baseArgs)
708		if filters.TaskID != "" {
709			where = append(where, fmt.Sprintf("t.task_name ILIKE $%d", argPos))
710			args = append(args, "%"+filters.TaskID+"%")
711			argPos++
712		}
713		if filters.Title != "" {
714			where = append(where, fmt.Sprintf("t.title ILIKE $%d", argPos))
715			args = append(args, "%"+filters.Title+"%")
716			argPos++
717		}
718		if filters.Status != "" {
719			statuses := splitCSV(filters.Status)
720			if len(statuses) == 1 {
721				where = append(where, fmt.Sprintf("t.status = $%d", argPos))
722				args = append(args, statuses[0])
723				argPos++
724			} else if len(statuses) > 1 {
725				where = append(where, fmt.Sprintf("t.status = ANY($%d)", argPos))
726				args = append(args, statuses)
727				argPos++
728			}
729		}
730		if filters.Repo != "" {
731			where = append(where, fmt.Sprintf("t.repo = $%d", argPos))
732			args = append(args, filters.Repo)
733			argPos++
734		}
735		return where, args, argPos
736	}
