738	// CountWorkspaceFeatures returns the total number of features matching the filters (ignores Page/Limit).
739	func (r *Reader) CountWorkspaceFeatures(ctx context.Context, workspaceID string, filters FeatureSearchFilters) (int, error) {
740		uid, err := parseUUID(workspaceID)
741		if err != nil {
742			return 0, err
743		}
744		where, args, _ := buildFeatureWhere(uid, filters)
745		q := fmt.Sprintf(`SELECT COUNT(*) FROM workspace_features WHERE %s`, strings.Join(where, " AND "))
746		var count int
747		if err := r.db.QueryRow(ctx, q, args...).Scan(&count); err != nil {
748			return 0, err
749		}
750		return count, nil
751	}
