753	// CountWorkspaceTasks returns the total number of tasks in a workspace matching the filters.
754	func (r *Reader) CountWorkspaceTasks(ctx context.Context, workspaceID string, filters TaskSearchFilters) (int, error) {
755		uid, err := parseUUID(workspaceID)
756		if err != nil {
757			return 0, err
758		}
759		where, args, _ := buildTaskWhere([]string{"t.workspace_id = $1"}, []interface{}{uid}, 2, filters)
760		q := fmt.Sprintf(`SELECT COUNT(*) FROM workspace_tasks t WHERE %s`, strings.Join(where, " AND "))
761		var count int
762		if err := r.db.QueryRow(ctx, q, args...).Scan(&count); err != nil {
763			return 0, err
764		}
765		return count, nil
766	}
767	
768	// CountFeatureTasks returns the total number of tasks in a feature matching the filters.
769	func (r *Reader) CountFeatureTasks(ctx context.Context, workspaceID, featureID string, filters TaskSearchFilters) (int, error) {
770		uid, err := parseUUID(workspaceID)
771		if err != nil {
772			return 0, err
773		}
774		fid, err := parseUUID(strings.TrimSpace(featureID))
775		if err != nil {
776			return 0, ErrNotFound
777		}
778		where, args, _ := buildTaskWhere([]string{"t.workspace_id = $1", "t.feature_id = $2"}, []interface{}{uid, fid}, 3, filters)
779		q := fmt.Sprintf(`SELECT COUNT(*) FROM workspace_tasks t WHERE %s`, strings.Join(where, " AND "))
780		var count int
