795	func taskIDNumberExpr() string {
796		return "NULLIF(regexp_replace(t.task_name, '^T([0-9]+)$', '\\1'), t.task_name)::int"
797	}
798	
799	func activityFilterClause(featureID, taskID string, firstArg int) (string, []interface{}, int, error) {
800		var where []string
801		var args []interface{}
802		argPos := firstArg
803		if featureID != "" {
804			fid, err := parseUUID(featureID)
805			if err != nil {
806				return "", nil, argPos, err
807			}
808			where = append(where, fmt.Sprintf("feature_id = $%d", argPos))
809			args = append(args, fid)
810			argPos++
811		}
812		if taskID != "" {
813			tid, err := parseUUID(taskID)
814			if err != nil {
815				return "", nil, argPos, err
816			}
817			where = append(where, fmt.Sprintf("task_id = $%d", argPos))
818			args = append(args, tid)
819			argPos++
820		}
821		if len(where) == 0 {
822			return "", nil, argPos, nil
823		}
824		return " AND " + strings.Join(where, " AND "), args, argPos, nil
825	}
826	
827	func (r *Reader) searchTasks(ctx context.Context, baseWhere []string, baseArgs []interface{}, argPos int, filters TaskSearchFilters) ([]WorkspaceTask, error) {
828		where, args, argPos := buildTaskWhere(baseWhere, baseArgs, argPos, filters)
829	
830		orderBy := taskIDOrderAsc()
831		switch filters.Sort {
832		case "task_id_desc":
833			orderBy = taskIDOrderDesc()
834		case "title_asc":
835			orderBy = "t.title ASC, " + taskIDOrderAsc()
836		case "title_desc":
837			orderBy = "t.title DESC, " + taskIDOrderAsc()
838		case "status_asc":
839			orderBy = "t.status ASC NULLS LAST, " + taskIDOrderAsc()
840		case "status_desc":
841			orderBy = "t.status DESC NULLS LAST, " + taskIDOrderAsc()
842		case "repo_asc":
843			orderBy = "t.repo ASC NULLS LAST, " + taskIDOrderAsc()
844		case "repo_desc":
845			orderBy = "t.repo DESC NULLS LAST, " + taskIDOrderAsc()
846		case "updated_at_asc", "time_asc", "createdAt":
847			orderBy = "t.updated_at ASC, " + taskIDOrderAsc()
848		case "updated_at_desc", "time_desc", "-createdAt":
849			orderBy = "t.updated_at DESC, " + taskIDOrderAsc()
850		case "task_id_asc", "":
851			orderBy = taskIDOrderAsc()
852		}
853	
854		limitClause := ""
855		if filters.Limit > 0 {
856			limitClause = fmt.Sprintf(" LIMIT $%d", argPos)
857			args = append(args, filters.Limit)
858			argPos++
859		}
860		offsetClause := ""
861		if filters.Page > 1 && filters.Limit > 0 {
862			offsetClause = fmt.Sprintf(" OFFSET $%d", argPos)
863			args = append(args, (filters.Page-1)*filters.Limit)
864		}
865	
866		q := fmt.Sprintf(`
867			SELECT t.id, t.workspace_id, t.feature_id, t.feature_name, t.task_id, t.task_name, t.title,
868			       t.repo, t.status, t.depends_on, t.blocked_reason, t.branch, t.execution,
869			       t.pr, t.workspace_pr, t.source_path, t.source_hash, t.created_at, t.updated_at
870			FROM workspace_tasks t
871			WHERE %s
872			ORDER BY %s%s%s`, strings.Join(where, " AND "), orderBy, limitClause, offsetClause)
873		rows, err := r.db.Query(ctx, q, args...)
874		if err != nil {
875			return nil, err
876		}
877		defer rows.Close()
878	
879		var out []WorkspaceTask
880		for rows.Next() {
881			var t WorkspaceTask
882			if err := scanTask(rows, &t); err != nil {
883				return nil, err
884			}
885			out = append(out, t)
886		}
887		return out, rows.Err()
888	}
