890	func splitCSV(value string) []string {
891		parts := strings.Split(value, ",")
892		out := make([]string, 0, len(parts))
893		for _, part := range parts {
894			trimmed := strings.TrimSpace(part)
895			if trimmed != "" {
896				out = append(out, trimmed)
897			}
898		}
899		return out
